func:
// ============================================================
// DEVICE INSTANCE REGISTRY - SINGLE SOURCE OF TRUTH
// ============================================================
// Pins every virtual device published by this boat's Node-RED
// flows to a fixed, hand-assigned VRM/device instance in the
// reserved block 200-255. Venus OS auto-assigns natively
// discovered devices from 0 upward and never reaches this
// block, so pinned instances cannot collide with a native
// device.
//
// Service name = com.victronenergy.<cls>.virtual_<nodeId> (the
// palette derives it from the Node-RED node ID). It stays
// deterministic as long as node IDs are hand-written, dot-free
// and never regenerated (no copy/paste re-import of device
// nodes). Signal K keys its paths off BOTH the service name
// and the instance, so both must stay stable across deploys.
//
// RULES
// - This table is the ONLY authority for instance numbers.
//   Nothing may derive an instance from array index, discovery
//   order, loop counter, timestamp or hash.
// - Never reuse an instance, even after deleting a device.
// - Blocks: 200-209 batteries, 210-219 motor drives,
//   220-239 switches, 240-255 spare.
// - The allocation table is mirrored in specification.md
//   ("Device instance allocation"); this node is authoritative.

const REGISTRY = [
    { nodeId: 'bat1_virtual',      cls: 'battery',    instance: 201, name: 'House 12V',             flowFile: 'BatteriesForward.json',    source: 'N2K addr 16, PGN 127506/127508' },
    { nodeId: 'bat2_virtual',      cls: 'battery',    instance: 202, name: 'Bow 12V',               flowFile: 'BatteriesForward.json',    source: 'N2K addr 16, PGN 127506/127508' },
    { nodeId: 'bat3_virtual',      cls: 'battery',    instance: 203, name: 'Stern 12V',             flowFile: 'BatteriesForward.json',    source: 'N2K addr 16, PGN 127506/127508' },
    { nodeId: 'bat4_virtual',      cls: 'battery',    instance: 204, name: 'Port Engine 12V',       flowFile: 'BatteriesForward.json',    source: 'PGN 127489 src 141, engine instance 0' },
    { nodeId: 'bat5_virtual',      cls: 'battery',    instance: 205, name: 'Starboard Engine 12V',  flowFile: 'BatteriesForward.json',    source: 'PGN 127489 src 142, engine instance 1' },
    { nodeId: 'gl6gk_port',        cls: 'motordrive', instance: 210, name: 'Port E-Motor',          flowFile: 'GreenlineEDriveFlow.json', source: 'CANopen node 0x0A, PGN 127493 instance 0' },
    { nodeId: 'gl6gk_stbd',        cls: 'motordrive', instance: 211, name: 'Starboard E-Motor',     flowFile: 'GreenlineEDriveFlow.json', source: 'CANopen node 0x0B, PGN 127493 instance 1' }
];
// Retired 2026-08-21: sp_switch_001 / sp_rated_switch (switch, 221/222,
// SolarPriority.json). The dbus-solarpriority driver took over 221 with
// the toggle AND the slider on one service (see EXTERNAL); 222 is retired
// and must never be reused. Not listed here for the same reason as the
// CZone rows below: a row would re-create the virtual_sp_* settings and
// hide them from the orphan audit. The flow is in archive/.
// Retired 2026-08-18: cz_vs_sw1-11 (switch, 225-235, CZoneProxy.json).
// dbus-czone replaced all eleven with ONE bank at instance 224 (see
// EXTERNAL below). They are deliberately NOT listed here: a row would
// re-create /Settings/Devices/virtual_cz_vs_swN on every enforcement
// pass AND hide the entries from the orphan audit, which is what the
// dbus-czone migration needs to remove. The flow is in archive/.

// Instances owned by standalone (non-Node-RED) dbus services.
// Reserved here so the sanity check blocks reuse. Each service pins
// its own instance via /Settings/Devices/<id>/ClassAndVrmInstance
// (no virtual_ prefix, so the palette auto-cleanup never touches it
// and this flow's enforcement/audit ignores it by design).
const EXTERNAL = [
    { nodeId: 'recbms',           cls: 'battery', instance: 200, name: 'REC-BMS Main Bank', flowFile: 'dbus-recbms/', source: 'standalone dbus-recbms service (was Virtual BMS.json)' },
    { nodeId: 'recbms_maxcharge', cls: 'switch',  instance: 220, name: 'Max Charge Slider', flowFile: 'dbus-recbms/', source: 'standalone dbus-recbms service (was Virtual BMS.json)' },
    { nodeId: 'czone',            cls: 'switch',  instance: 224, name: 'CZone switch bank', flowFile: 'dbus-czone/',  source: 'standalone dbus-czone service (was CZoneProxy.json); ONE multi-output bank replaces cz_vs_sw1-11 / 225-235' },
    { nodeId: 'solarpriority',    cls: 'switch',  instance: 221, name: 'Solar Priority',    flowFile: 'dbus-recbms/', source: 'standalone dbus-solarpriority service (was SolarPriority.json); toggle + PV capacity slider on one service, 222 retired' }
];

flow.set('ir_registry', REGISTRY);

// Sanity: reserved range, unique instance per class, unique
// service, node IDs safe for dbus paths (and dot-free — a palette
// constraint since 1.6.x, still required at 1.7.18).
const seen = {};
for (const d of REGISTRY.concat(EXTERNAL)) {
    if (d.instance < 200 || d.instance > 255) { node.error('Registry: instance outside reserved block 200-255: ' + d.nodeId); return null; }
    const ki = 'i:' + d.cls + ':' + d.instance, ks = 's:' + d.nodeId;
    if (seen[ki] || seen[ks]) { node.error('Registry: duplicate entry: ' + d.nodeId); return null; }
    seen[ki] = true; seen[ks] = true;
    if (/[^A-Za-z0-9_]/.test(d.nodeId)) { node.error('Registry: node ID must be [A-Za-z0-9_] only: ' + d.nodeId); return null; }
}

// Idempotent enforcement as ONE python3 batch over a single
// dbus connection (fed to the exec node via heredoc). One
// process instead of ~70 dbus CLI spawns: each CLI call costs
// ~1.5s of interpreter startup on the loaded Cerbo, which blew
// the exec timeout and truncated the pass mid-device.
//  1. AddSetting pre-seeds ClassAndVrmInstance if missing (it
//     keeps an existing value, so re-runs never clobber).
//  2. SetValue pins it when it differs from the registry.
//  3. The LIVE /DeviceInstance is compared. RECONVERGE means
//     the service registered before the pin landed - one more
//     deploy converges it in place; the service NAME never
//     changes, so nothing new is ever created.
// The audit then dumps all virtual_* settings entries and all
// live virtual services so the parser can flag orphans.
const rows = REGISTRY.map(function (d) { return { id: d.nodeId, cls: d.cls, inst: d.instance }; });
const py = [];
py.push('import dbus');
py.push('REG = ' + JSON.stringify(rows));
py.push('BUS = dbus.SystemBus()');
py.push("BI = 'com.victronenergy.BusItem'");
py.push("SV = 'com.victronenergy.settings'");
py.push('def val(service, path):');
py.push('    try:');
py.push('        return BUS.get_object(service, path).GetValue(dbus_interface=BI)');
py.push('    except Exception:');
py.push('        return None');
py.push('for d in REG:');
py.push("    sn = 'virtual_' + d['id']");
py.push("    want = d['cls'] + ':' + str(d['inst'])");
py.push("    p = '/Settings/Devices/' + sn + '/ClassAndVrmInstance'");
py.push('    cur = val(SV, p)');
py.push('    if cur is None:');
py.push('        try:');
py.push("            BUS.get_object(SV, '/Settings').AddSetting('Devices/' + sn, 'ClassAndVrmInstance', want, 's', 0, 0, dbus_interface='com.victronenergy.Settings')");
py.push('        except Exception as e:');
py.push("            print('ERROR AddSetting ' + sn + ': ' + str(e))");
py.push('            continue');
py.push('        cur = val(SV, p)');
py.push('    cur = None if cur is None else str(cur)');
py.push('    if cur != want:');
py.push('        try:');
py.push('            BUS.get_object(SV, p).SetValue(want, dbus_interface=BI)');
py.push("            print('PINNED ' + sn + ' ' + (cur or 'none') + ' to ' + want)");
py.push('        except Exception as e:');
py.push("            print('ERROR SetValue ' + sn + ': ' + str(e))");
py.push('    else:');
py.push("        print('OK ' + sn + ' ' + want)");
py.push("    live = val('com.victronenergy.' + d['cls'] + '.' + sn, '/DeviceInstance')");
py.push('    if live is None:');
py.push("        print('NOT-RUNNING ' + sn)");
py.push("    elif int(live) != d['inst']:");
py.push("        print('RECONVERGE ' + sn + ' live ' + str(int(live)) + ' pinned ' + str(d['inst']))");
py.push("print('AUDIT-SETTINGS')");
py.push("tree = val(SV, '/Settings/Devices')");
py.push("if hasattr(tree, 'keys'):");
py.push('    for k in sorted(str(x) for x in tree.keys()):');
py.push("        if k.startswith('virtual_'):");
py.push('            print(k)');
py.push("print('AUDIT-LIVE')");
py.push('for name in sorted(str(x) for x in BUS.list_names()):');
py.push("    if name.startswith('com.victronenergy.') and 'virtual_' in name:");
py.push('        print(name)');
py.push("print('AUDIT-END')");

node.status({ fill: 'blue', shape: 'dot', text: 'enforcing ' + REGISTRY.length + ' pinned devices' });
msg.payload = 'python3 - <<\'PYEOF\'\n' + py.join('\n') + '\nPYEOF';
return msg;

// Parses the enforcement/audit output. Orphans = settings
// entries for virtual_* services that are neither in the
// registry nor currently live (safe to remove). Live services
// missing from the registry are flagged but NEVER queued for
// removal (e.g. an older flow version still deployed on the
// boat, like CZone v5).
// A truncated run (no AUDIT-END) is reported as an error so a
// killed/timed-out pass can never masquerade as a clean one.
const REG = flow.get('ir_registry') || [];
const known = {};
REG.forEach(function (d) { known['virtual_' + d.nodeId] = true; });

const text = (typeof msg.payload === 'string') ? msg.payload : String(msg.payload || '');
const ok = [], pinned = [], reconverge = [], notRunning = [], errors = [];
const settingsKeys = [], liveSvcs = {};
let section = '', sawEnd = false;
text.split('\n').forEach(function (raw) {
    const t = raw.trim();
    if (!t) return;
    if (t === 'AUDIT-SETTINGS') { section = 'settings'; return; }
    if (t === 'AUDIT-LIVE') { section = 'live'; return; }
    if (t === 'AUDIT-END') { section = 'done'; sawEnd = true; return; }
    if (section === 'settings') { settingsKeys.push(t); return; }
    if (section === 'live') {
        const m = t.match(/virtual_[A-Za-z0-9_]+$/);
        if (m) liveSvcs[m[0]] = t;
        return;
    }
    if (t.indexOf('OK ') === 0) ok.push(t);
    else if (t.indexOf('PINNED ') === 0) pinned.push(t);
    else if (t.indexOf('RECONVERGE ') === 0) reconverge.push(t);
    else if (t.indexOf('NOT-RUNNING ') === 0) notRunning.push(t);
    else if (t.indexOf('ERROR ') === 0) errors.push(t);
});

if (!sawEnd) errors.push('ERROR run truncated (no AUDIT-END) - exec killed or timed out; counts below are incomplete');

const orphanKeys = [], orphanSvcs = {}, unmanagedLive = [];
if (sawEnd) {
    settingsKeys.forEach(function (k) {
        const svc = k.split('/')[0];
        if (known[svc]) return;
        if (liveSvcs[svc]) { if (unmanagedLive.indexOf(svc) < 0) unmanagedLive.push(svc); return; }
        orphanKeys.push(k);
        orphanSvcs[svc] = true;
    });
    Object.keys(liveSvcs).forEach(function (svc) {
        if (!known[svc] && unmanagedLive.indexOf(svc) < 0) unmanagedLive.push(svc);
    });
}

flow.set('ir_orphan_keys', orphanKeys);

const nOrph = Object.keys(orphanSvcs).length;
const summary = ok.length + ' ok, ' + pinned.length + ' pinned, ' + reconverge.length + ' await redeploy, ' + notRunning.length + ' not running, ' + nOrph + ' orphan, ' + unmanagedLive.length + ' unmanaged, ' + errors.length + ' error';

if (errors.length) node.warn('Enforcement errors: ' + errors.join(' | '));
if (reconverge.length) node.warn('Pinned in settings but service still live on the old instance (converges in place on the next deploy): ' + reconverge.join(' | '));
if (nOrph) node.warn('Orphan /Settings/Devices entries (dead services, removable via the cleanup inject): ' + Object.keys(orphanSvcs).join(', '));
if (unmanagedLive.length) node.warn('LIVE virtual services not in the registry - add them to the table: ' + unmanagedLive.join(', '));

node.status({ fill: errors.length ? 'red' : ((reconverge.length || nOrph || unmanagedLive.length) ? 'yellow' : 'green'), shape: 'dot', text: summary });

msg.payload = {
    summary: summary,
    ok: ok, pinned: pinned, reconverge: reconverge, notRunning: notRunning, errors: errors,
    orphanSettings: orphanKeys, unmanagedLiveServices: unmanagedLive
};
return msg;

// Builds a RemoveSettings call for the orphan entries recorded
// by the last audit. Only DEAD services are ever queued (the
// audit excludes live ones), so this cannot disturb a running
// device. Run the audit first and review its orphan warning
// before pressing this.
const keys = flow.get('ir_orphan_keys') || [];
if (!keys.length) {
    node.status({ fill: 'grey', shape: 'ring', text: 'no orphans recorded - run the audit first' });
    return null;
}
const arr = keys.map(function (k) { return '"Devices/' + k + '"'; }).join(',');
msg.payload = 'dbus -y com.victronenergy.settings /Settings RemoveSettings \'%[' + arr + ']\'';
node.status({ fill: 'yellow', shape: 'dot', text: 'removing ' + keys.length + ' orphan setting(s)' });
return msg;
